var import_obsidian4 = require("obsidian");
var FileIndex = class {
  constructor(plugin) {
    this.plugin = plugin;
    this._index = {};
  }
  getFileDataIndex() {
    return this._index;
  }
  init() {
    const thisObj = this;
    this.initIndex().then();
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
    }
    let intervalMs = indexRefreshTime;
    if (this.plugin.settings.fileIndexRefreshInterval > 0) {
      intervalMs = this.plugin.settings.fileIndexRefreshInterval * 1e3;
    }
    this.refreshInterval = setInterval(() => {
      thisObj.updateFileIndex().then();
    }, intervalMs);
  }
  restartIndexing() {
    const thisObj = this;
    this.initIndex().then();
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
    }
    let intervalMs = indexRefreshTime;
    if (this.plugin.settings.fileIndexRefreshInterval > 0) {
      intervalMs = this.plugin.settings.fileIndexRefreshInterval * 1e3;
    }
    this.refreshInterval = setInterval(() => {
      thisObj.updateFileIndex().then();
    }, intervalMs);
  }
  destroy() {
    clearInterval(this.refreshInterval);
  }
  async initIndex() {
    const obsidianApp = this.plugin.app;
    const fileIndexPath = this.plugin.settings.fileIndexPath;
    if (!fileIndexPath || !this.plugin.settings.fileIndexEnabled) {
      this._index = {};
      return this._index;
    }
    let csvFile = obsidianApp.vault.getFileByPath(fileIndexPath);
    if (csvFile == null) {
      csvFile = await obsidianApp.vault.create(fileIndexPath, "");
    }
    let index = {};
    const indexDump = await obsidianApp.vault.read(csvFile);
    const dateFormat = indexDateFormat;
    if (indexDump) {
      import_papaparse.default.parse(indexDump, {
        complete: function(results) {
          const data = results.data;
          for (let i2 = 1; i2 < data.length; i2++) {
            const row = data[i2];
            const filePath = row[0];
            const fileDate = (0, import_obsidian4.moment)(row[1], dateFormat).toDate();
            const entryProtected = row[2] == "TRUE";
            const deletionDate = row[3] ? (0, import_obsidian4.moment)(row[3], dateFormat).toDate() : null;
            index[filePath] = {
              path: filePath,
              creationDate: fileDate,
              isProtected: entryProtected,
              deletionDate
            };
          }
        }
      });
    }
    this._index = index;
    return index;
  }
  async updateFileIndex(oneTimeExec = false) {
    if (!this.plugin.settings.fileIndexEnabled && !oneTimeExec) {
      return;
    }
    const obsidianApp = this.plugin.app;
    const { vault, metadataCache } = obsidianApp;
    let fileIndexPath = this.plugin.settings.fileIndexPath;
    if (!fileIndexPath) {
      if (!oneTimeExec) {
        new import_obsidian4.Notice("[Vault size history] File index path not configured, cannot rebuild the index");
        return;
      }
      fileIndexPath = DEFAULT_SETTINGS.fileIndexPath;
    }
    if (oneTimeExec) {
      new import_obsidian4.Notice("[Vault size history] Updating file index");
    }
    let index = await this.initIndex();
    let csvFile = obsidianApp.vault.getFileByPath(fileIndexPath);
    if (csvFile == null) {
      csvFile = await obsidianApp.vault.create(fileIndexPath, "");
    }
    const files = vault.getFiles();
    const indexedPaths = Object.keys(index);
    const obsidianCachedPaths = [];
    const updatedIndexEntries = [];
    for (const file of files) {
      let fileCreatedDate = new Date(file.stat.ctime);
      const indexEntry = index[file.path];
      if (indexEntry && (fileCreatedDate > indexEntry.creationDate || indexEntry.isProtected)) {
        fileCreatedDate = indexEntry.creationDate;
      }
      updatedIndexEntries.push(
        {
          path: file.path,
          creationDate: fileCreatedDate,
          isProtected: indexEntry ? indexEntry.isProtected : false,
          deletionDate: null
        }
      );
      obsidianCachedPaths.push(file.path);
    }
    const missingFiles = indexedPaths.filter((element) => !obsidianCachedPaths.includes(element));
    for (const path of missingFiles) {
      const indexEntryDeletedFile = index[path];
      if (!indexEntryDeletedFile.deletionDate) {
        indexEntryDeletedFile.deletionDate = new Date();
      }
      updatedIndexEntries.push(indexEntryDeletedFile);
    }
    updatedIndexEntries.sort((a2, b) => {
      if (a2.path < b.path)
        return -1;
      if (a2.path > b.path)
        return 1;
      return 0;
    });
    await obsidianApp.vault.modify(csvFile, '"File Path","Created Date (System)","Protect Date","Deleted Date"\r\n');
    const newCSVContent = import_papaparse.default.unparse(updatedIndexEntries, {
      quotes: true,
      header: false,
      columns: [
        "path",
        "creationDate",
        "isProtected",
        "deletionDate"
      ]
    });
    await obsidianApp.vault.append(
      csvFile,
      newCSVContent
    );
    if (oneTimeExec) {
      new import_obsidian4.Notice("[Vault size history] Index file updated successfully");
    }
    await this.initIndex();
  }
};

// main.ts
var VaultSizeHistoryPlugin = class extends import_obsidian5.Plugin {
  async onload() {
    await this.loadSettings();
    this.addSettingTab(new MainSettingTab(this.app, this));
    this.addCommand({
      id: "open-graph-modal",
      name: "Open graph",
      callback: () => {
        this.activateView();
      }
    });
    this.addRibbonIcon("area-chart", "Vault size history", () => {
      this.activateView();
    });
    this.fileIndex = new FileIndex(this);
    this.fileIndex.init();
  }
  onunload() {
    this.fileIndex.destroy();
  }
  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }
  async saveSettings() {
    await this.saveData(this.settings);
  }
  async activateView() {
    new GraphModal(this.app, this).open();
  }
};
